// src/server/repo/leave-types.ts — leave type queries (FR-902, X48, plan/m05 S0.12/S2.3). Order: ORDER BY position,
// id. Order keys are generated by the service under lockOrderScope(tx, 'leave_types').
import { and, asc, count, desc, eq, isNull, ne, sql } from 'drizzle-orm'
import type { DbOrTx } from '../db/types'
import { leaveTypes, timeOff, type LeaveTypeRow } from '../db/schema'
import { NotFoundError } from '../errors'

export type { LeaveTypeRow } from '../db/schema'

/** `id` / `archivedAt` only for undo re-inserts (restoreLeaveType keeps id, name, colour and position). */
export async function insertLeaveType(
  tx: DbOrTx,
  v: { id?: string; name: string; color: string; position: string; archivedAt?: Date | null },
): Promise<LeaveTypeRow> {
  const rows = await tx.insert(leaveTypes).values(v).returning()
  const [row] = rows
  if (!row) throw new Error('insert failed')
  return row
}

export interface LeaveTypeListRow extends LeaveTypeRow {
  /** Live (not soft-deleted) time_off rows that use the type. */
  usageCount: number
}

/** ORDER BY position, id; `includeArchived: false` → active only. */
export function listOrdered(tx: DbOrTx, opts: { includeArchived: boolean }): Promise<LeaveTypeListRow[]> {
  return tx
    .select({
      id: leaveTypes.id,
      name: leaveTypes.name,
      color: leaveTypes.color,
      position: leaveTypes.position,
      archivedAt: leaveTypes.archivedAt,
      // Qualified by hand: drizzle renders column refs inside a raw subquery without their table name.
      usageCount: sql<number>`(select count(*)::int from "time_off" t where t."leave_type_id" = "leave_types"."id" and t."deleted_at" is null)`,
    })
    .from(leaveTypes)
    .where(opts.includeArchived ? undefined : isNull(leaveTypes.archivedAt))
    .orderBy(asc(leaveTypes.position), asc(leaveTypes.id))
}

export async function getLeaveType(tx: DbOrTx, id: string): Promise<LeaveTypeRow | null> {
  const [row] = await tx.select().from(leaveTypes).where(eq(leaveTypes.id, id))
  return row ?? null
}

export async function getOrNotFound(tx: DbOrTx, id: string): Promise<LeaveTypeRow> {
  const row = await getLeaveType(tx, id)
  if (!row) throw new NotFoundError()
  return row
}

/** Id of the type with exactly this name (archived included — names are unique across both), else null. */
export async function findIdByName(tx: DbOrTx, name: string): Promise<string | null> {
  const [row] = await tx.select({ id: leaveTypes.id }).from(leaveTypes).where(eq(leaveTypes.name, name))
  return row?.id ?? null
}

/** The last order key (ORDER BY position DESC, id DESC), or null when the table is empty. */
export async function lastPosition(tx: DbOrTx): Promise<string | null> {
  const [row] = await tx
    .select({ position: leaveTypes.position })
    .from(leaveTypes)
    .orderBy(desc(leaveTypes.position), desc(leaveTypes.id))
    .limit(1)
  return row?.position ?? null
}

/** Every time_off row (live or soft-deleted) that references the type — the FK is RESTRICT (M5-D10). */
export async function countReferences(tx: DbOrTx, id: string): Promise<number> {
  const [row] = await tx.select({ n: count() }).from(timeOff).where(eq(timeOff.leaveTypeId, id))
  return row?.n ?? 0
}

/** Active (not archived) types, optionally excluding one id. */
export async function countActive(tx: DbOrTx, exceptId?: string): Promise<number> {
  const [row] = await tx
    .select({ n: count() })
    .from(leaveTypes)
    .where(and(isNull(leaveTypes.archivedAt), exceptId ? ne(leaveTypes.id, exceptId) : undefined))
  return row?.n ?? 0
}

export async function countAll(tx: DbOrTx): Promise<number> {
  const [row] = await tx.select({ n: count() }).from(leaveTypes)
  return row?.n ?? 0
}

export async function updateRow(
  tx: DbOrTx,
  id: string,
  v: Partial<Pick<LeaveTypeRow, 'name' | 'color' | 'position' | 'archivedAt'>>,
): Promise<void> {
  await tx.update(leaveTypes).set(v).where(eq(leaveTypes.id, id))
}

/** Hard delete (23503 when a time_off row references it). */
export async function deleteRow(tx: DbOrTx, id: string): Promise<void> {
  await tx.delete(leaveTypes).where(eq(leaveTypes.id, id))
}
